INSERT INTO Language_ko_KR (Tag, Text)
VALUES	('TXT_KEY_BUILDING_SUPERMARKET',			'슈퍼마켓'),
		('TXT_KEY_BUILDING_SUPERMARKET_TEXT',		'슈퍼마켓은 고객이 직접 선반에서 물건을 골라 구매할 수 있는 다양한 종류의 식품, 음료, 가정용품을 판매하는 대형 매장입니다. 최초의 셀프 서비스 슈퍼마켓은 1916년 테네시주 멤피스에 문을 열었고, 이 아이디어는 북미 전역으로 순식간에 퍼졌습니다. 현대 슈퍼마켓은 도시 거주자들의 쇼핑에 혁명을 일으켜, 노동력을 대폭 줄이고 일상 필수품의 비용을 절감했습니다.'),
		('TXT_KEY_BUILDING_SUPERMARKET_STRATEGY',	'슈퍼마켓은 성장하는 대도시를 위한 원자력 시대 건물입니다. 많은 양의 골드를 지출하면 손쉽게 인구 증가로 전환할 수 있으며, 수도와 연결된 대규모 도시에서 생산되는 산출량이 더욱 향상됩니다! 슈퍼마켓을 짓기 위해서는 도시가 이미 상당히 개발되어야 하지만, 그 보상은 엄청납니다!'),
		('TXT_KEY_BUILDING_SUPERMARKET_HELP',		'이 도시에서 [ICON_INVEST] 골드를 사용하여 유닛을 구매하거나 건물에 투자할 경우, 비용의 25%가 [ICON_FOOD] 식량으로 전환됩니다. [ICON_INDUSTRIAL_CONNECTED] 지역 도시와의 연결로 인해 [ICON_GOLD] 골드와 [ICON_PRODUCTION] 생산이 +50% 증가합니다. 이 도시의 내부 [ICON_INTERNATIONAL_TRADE] 교역로에서 [ICON_FOOD] 식량이 +10만큼 증가합니다.[NEWLINE][NEWLINE]이 도시의 전문가 1명이 더 이상 [ICON_URBANIZATION] 도시화로 인한 [ICON_HAPPINESS_3] 불행을 생성하지 않습니다.[NEWLINE][NEWLINE]건설하려면 [ICON_INDUSTRIAL_CONNECTED] 산업 도시와 연결되어야 합니다.');